import{_ as t,o,c as r,a2 as i}from"./chunks/framework.BXzK3EA4.js";const a="/assets/image%20(93).BfzNGtqp.png",n="/assets/image%20(92).CB4XjHwh.png",s="/assets/image%20(91).D4LwtkU0.png",m=JSON.parse('{"title":"Chrome Extension","description":"","frontmatter":{},"headers":[],"relativePath":"trading-platform/chrome-extension.md","filePath":"trading-platform/chrome-extension.md"}'),l={name:"trading-platform/chrome-extension.md"};function d(h,e,g,c,u,p){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="chrome-extension" tabindex="-1">Chrome Extension <a class="header-anchor" href="#chrome-extension" aria-label="Permalink to &quot;Chrome Extension&quot;">​</a></h1><p>A lightweight Chrome extension for the Tradeboard trading platform with a DaisyUI-inspired modern UI.</p><h3 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li><strong>Quick Trading Actions</strong>: Instantly place trades using LE (Long Entry), LX (Long Exit), SE (Short Entry), and SX (Short Exit) buttons.</li><li><strong>Minimal Interface</strong>: Compact, draggable layout that integrates directly onto chart pages.</li><li><strong>Integrated Settings Panel</strong>: Easy configuration using a settings popup with support for multiple exchanges and trading products.</li><li><strong>Modern UI</strong>: Styled using DaisyUI for a clean and efficient interface.</li><li><strong>Real-time Feedback</strong>: Visual confirmation for each trading action.</li></ul><h3 id="download-tradeboard-chrome-extension" tabindex="-1">Download Tradeboard Chrome Extension <a class="header-anchor" href="#download-tradeboard-chrome-extension" aria-label="Permalink to &quot;Download Tradeboard Chrome Extension&quot;">​</a></h3><p><a href="https://github.com/wesoftcorp/tradeboard-chrome/releases/tag/v1.0" target="_blank" rel="noreferrer">https://github.com/wesoftcorp/tradeboard-chrome/releases/tag/v1.0</a></p><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><ul><li><strong>Tradeboard API Server</strong>: The Tradeboard server must be running (locally or remotely) and accessible.</li><li><strong>API Key</strong>: A valid API key is required to authenticate API requests.</li><li><strong>Browser</strong>: Chrome version 88 or higher. (Recommended Latest Version of Chrome)</li></ul><h3 id="installation-guide" tabindex="-1">Installation Guide <a class="header-anchor" href="#installation-guide" aria-label="Permalink to &quot;Installation Guide&quot;">​</a></h3><h4 id="install-via-developer-mode" tabindex="-1">Install via Developer Mode <a class="header-anchor" href="#install-via-developer-mode" aria-label="Permalink to &quot;Install via Developer Mode&quot;">​</a></h4><ol><li>Open Chrome and go to <code>chrome://extensions/</code></li><li>Enable <strong>Developer mode</strong> (top right toggle)</li><li>Click on <strong>&quot;Load unpacked&quot;</strong></li><li>Select the folder you extracted from the <code>.zip</code> file</li><li>The Tradeboard extension icon will now appear in your Chrome toolbar</li></ol><figure><img src="'+a+'" alt=""><figcaption></figcaption></figure><h3 id="usage-guide" tabindex="-1">Usage Guide <a class="header-anchor" href="#usage-guide" aria-label="Permalink to &quot;Usage Guide&quot;">​</a></h3><h4 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h4><ol><li><strong>Start the Tradeboard Server</strong>: Make sure the Tradeboard server is running (default: <code>http://127.0.0.1:5000</code>)</li></ol><figure><img src="'+n+'" alt=""><figcaption></figcaption></figure><ol><li><strong>Configure Settings</strong>: <ul><li>Click the 3-dot menu icon next to the button panel</li><li>Fill in the following fields: <ul><li>Host URL (e.g., <code>http://127.0.0.1:5000</code>)</li><li>API Key</li><li>Symbol (e.g., <code>RELIANCE</code> or <code>NIFTY27APR25FUT</code>)</li><li>Exchange. The dropdown offers exactly six values: NSE, BSE, BFO, NFO, MCX and CDS</li><li>Product (MIS, NRML, CNC)</li><li>Quantity (e.g., 10, 20, etc.). Futures or Options symbols it is always the total number of shares instead of Lot Size</li></ul></li></ul></li><li><strong>Save Settings</strong>: Click <strong>Save</strong> to apply your configuration</li></ol><p>Settings are stored in Chrome&#39;s synced storage, so they follow your Chrome profile across machines. Every field is mandatory: if any one of them is blank the buttons refuse to fire and the settings panel opens instead.</p><figure><img src="'+s+'" alt=""><figcaption></figcaption></figure><h4 id="trading-actions" tabindex="-1">Trading Actions <a class="header-anchor" href="#trading-actions" aria-label="Permalink to &quot;Trading Actions&quot;">​</a></h4><ul><li><strong>LE (Green)</strong>: Long Entry (Buy to Open)</li><li><strong>LX (Yellow)</strong>: Long Exit (Sell to Close Long)</li><li><strong>SE (Red)</strong>: Short Entry (Sell to Open Short)</li><li><strong>SX (Blue)</strong>: Short Exit (Buy to Close Short)</li></ul><p>The two entry buttons post a MARKET order to <code>/api/v1/placeorder</code> with your configured Quantity, and Tradeboard records the strategy as <code>Chrome</code>.</p><p>The two exit buttons post to <code>/api/v1/placesmartorder</code> with <code>position_size</code> set to <code>0</code>. That tells Tradeboard to look up your live open position for that symbol, exchange and product and flatten it, whatever its size and direction. Two consequences worth knowing:</p><ul><li>An exit closes the whole position. The Quantity field in settings is not used for exits.</li><li>If there is no open position, nothing is sent to the broker and Tradeboard replies that the position already matches.</li></ul><p>The extension is a content script registered against all URLs, so the button bar can be injected on any page you have open, not only charting sites. It can be repositioned anywhere on the screen.</p><h4 id="draggable-interface" tabindex="-1">Draggable Interface <a class="header-anchor" href="#draggable-interface" aria-label="Permalink to &quot;Draggable Interface&quot;">​</a></h4><ul><li>Hover over the top edge of the trading bar to reveal the grab handle</li><li>Click and drag to reposition the widget anywhere on the screen</li></ul><h3 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h3><ul><li><strong>No Response from Buttons</strong>: <ul><li>Ensure the Tradeboard server is running</li><li>Double-check Host URL and API Key</li></ul></li><li><strong>Incorrect or Missing Settings</strong>: <ul><li>Reopen settings panel and verify all fields are filled</li></ul></li><li><strong>Server Connection Errors</strong>: <ul><li>Confirm the server is reachable at the provided Host URL</li></ul></li></ul><hr><p>The Tradeboard Chrome Extension is designed to simplify and streamline your trading experience. With a clean interface and real-time trading controls built right into your browser, it allows you to react quickly to market opportunities with just one click. Whether you&#39;re managing long or short positions, this extension brings the power of Tradeboard directly into your charting tools, making intraday trading more efficient and intuitive. Configure once, trade instantly, and let technology work for you while you focus on strategy.</p>',31)])])}const b=t(l,[["render",d]]);export{m as __pageData,b as default};
